import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.r0uj6mzT.js";const h=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1793543263000}'),n={name:"reference/glossary.md"};function r(i,e,d,p,c,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>Active root</strong> : An actor root that is currently managed.</p><p><strong>Actor root</strong> : An enabled dataset with no enabled ancestor. It owns its whole subtree: its lineage, target bindings, recovery state and jobs cover every member.</p><p><strong>Adoption</strong> : An explicit, preview-first transfer of an existing managed dataset lineage to the current installation.</p><p><strong>Dataset</strong> : An OpenZFS filesystem or volume. Boomerangz policy is attached to datasets using ZFS user properties.</p><p><strong>Destination root</strong> : The ZFS dataset beneath which received data is stored.</p><p><strong>Excluded dataset</strong> : A dataset inside an actor root&#39;s subtree that is not one of its members, because <code>enabled=off</code> applies to it. An excluded dataset with members beneath it is a hole, replicated only as an empty placeholder.</p><p><strong>Inactive grace period</strong> : The delay between deactivation and automatic retirement of recoverable Boomerangz state. The default is 24 hours.</p><p><strong>Lineage</strong> : The persistent identity of a managed dataset&#39;s history. It prevents a same-named replacement from being mistaken for the original data.</p><p><strong>Local destination</strong> : A destination dataset reached on the same host.</p><p><strong>Member</strong> : An enabled dataset inside an actor root&#39;s subtree. It is snapshotted, pruned and sent by its root, with its own grid and send options, and carries no Boomerangz state of its own.</p><p><strong>Native destination</strong> : Another Boomerangz installation reached through a secured paired listener.</p><p><strong>Pairing</strong> : A credential bundle that identifies a listener, establishes server trust, and carries the authentication material and scopes granted to a client.</p><p><strong>Placeholder</strong> : An empty dataset Boomerangz creates at a destination for a hole, so a deeper member&#39;s replica can be received beneath it. It is marked with <code>org.boomerangz:state:placeholder=on</code>, and every replica sets the marker <code>off</code>.</p><p><strong>Policy grid</strong> : The count-and-duration expression that sets snapshot cadence and retention, such as <code>24x1h,14x1d</code>.</p><p><strong>Replication</strong> : Sending a ZFS data stream to a destination dataset so it can be stored on separate storage or another host.</p><p><strong>Scheduling root</strong> : The actor root whose job snapshots or replicates its members.</p><p><strong>Snapshot</strong> : A read-only ZFS point-in-time view. A snapshot on the source pool is not an independent backup.</p>',18)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
